def check_records(T):
    results = []
    for _ in range(T):
        n = int(input())
        prev_p, prev_c = -1, -1
        valid = True
        for _ in range(n):
            p, c = map(int, input().split())
            if c < prev_c or (p < prev_p and c <= prev_c):
                valid = False
                break
            prev_p, prev_c = p, c
        results.append("YES" if valid else "NO")
    return "\n".join(results)

